# ######## CELL 23: OnlineHD with its own step size ########
# Estimated run time: ~3-4 h on an 8-core High-RAM CPU runtime (no GPU needed).
# 126 jobs (7 datasets x rp/nonlinear x D 512/2048/8192 x 3 seeds). Each job trains perceptron
# retraining, OnlineHD with the shared step size (as in the paper) and OnlineHD with a step
# size tuned for its own rule on the validation split (grid 0.01-3), then evaluates FP32/4-bit/
# binary on 3 devices with 8 chips at 1 day, plus one calibration chip (sigma_Delta) and the
# median cosine margin. Output: results/v3_onlinehd.jsonl (resumable). Can run at the same time
# as cell 22 in a second notebook.

STAGE     = "onlinehd"
DRIVE_DIR = "/content/drive/MyDrive/hdc_memristive"

import os, subprocess, sys, pathlib
from google.colab import drive
drive.mount("/content/drive")
work = pathlib.Path(DRIVE_DIR); code = work / "code_rev_onlinehd"; code.mkdir(parents=True, exist_ok=True)

FILES = {'hdc.py': '"""Hyperdimensional computing (HDC) with class prototypes stored in a memristive crossbar.\n\nPipeline\n  1. Encode each sample with a random projection: h = sign(x P), P ~ N(0, 1)^(F x D),\n     giving bipolar query hypervectors that drive the crossbar rows as +/-V pulses.\n  2. Train class prototypes in software: one bundling pass (sum of class hypervectors),\n     then optional perceptron-style retraining epochs (standard in HDC literature).\n  3. L2-normalise each prototype (dot product -> cosine similarity) and quantise it to\n     the chosen precision (fp / k-bit / binary).\n  4. Program the prototypes into an AIHWKit inference tile with a device noise model\n     calibrated on real hardware (PCM, NeuRRAM ReRAM, CMO/HfOx ReRAM), let them drift\n     for time t, and classify by argmax over the analog dot products.\nEvery (device, D, precision, t) point is evaluated over several independently\nprogrammed "chips" (Monte Carlo) so device-to-device spread shows up as variance.\n"""\nfrom __future__ import annotations\n\nimport warnings\nfrom dataclasses import dataclass\n\nimport numpy as np\nimport torch\n\nwarnings.filterwarnings("ignore")\n\n# ----------------------------------------------------------------------------- data\nOPENML = {  # name -> (openml name, version, standard split)\n    "isolet": ("isolet", 1, None),\n    "ucihar": ("har", 1, None),\n    "mnist": ("mnist_784", 1, 60000),\n    "fmnist": ("Fashion-MNIST", 1, 60000),\n    "letter": ("letter", 1, None),\n    "pendigits": ("pendigits", 1, None),\n    "satimage": ("satimage", 1, None),\n}\nALL_DATASETS = list(OPENML)\n\n# European language recognition (Joshi, Halseth, Kanerva 2016; Rahimi et al. ISLPED 2016):\n# 22 training languages, 21,000 test sentences (21 languages; Afrikaans has no test set).\nLANGID_REPO = "https://github.com/abbas-rahimi/HDC-Language-Recognition"\nLANGID_COMMIT = "b3be34dd7caa2dc0c13be60447e74956e64cfd33"\nLANGID_LABELS = ["afr", "bul", "ces", "dan", "nld", "deu", "eng", "est", "fin", "fra", "ell",\n                 "hun", "ita", "lav", "lit", "pol", "por", "ron", "slk", "slv", "spa", "swe"]\nLANGID_TEST = {"af": "afr", "bg": "bul", "cs": "ces", "da": "dan", "nl": "nld", "de": "deu",\n               "en": "eng", "et": "est", "fi": "fin", "fr": "fra", "el": "ell", "hu": "hun",\n               "it": "ita", "lv": "lav", "lt": "lit", "pl": "pol", "pt": "por", "ro": "ron",\n               "sk": "slk", "sl": "slv", "es": "spa", "sv": "swe"}\nLANGID_CHUNK = 150      # training sample length (characters), close to the mean test sentence\nLANGID_PER_LANG = 2000  # training chunks drawn per language\nLANGID_MAXLEN = 1200    # longest test sentence is 1,138 characters\nN_SYMBOLS = 27          # a-z and space; any other character is read as a space\n\n\ndef _trigram_ids(text: str, maxlen: int) -> np.ndarray:\n    """Trigram index sequence (c[t-2]*729 + c[t-1]*27 + c[t]), padded with -1."""\n    c = np.frombuffer(text.lower().encode("latin-1", "replace"), dtype=np.uint8).astype(np.int32) - 97\n    c = np.where((c >= 0) & (c < 26), c, 26)[:maxlen]\n    g = c[:-2] * 729 + c[1:-1] * 27 + c[2:] if len(c) >= 3 else np.zeros(0, np.int32)\n    out = np.full(maxlen, -1, np.int16)\n    out[:len(g)] = g\n    return out\n\n\ndef _load_langid(data_home: str):\n    import os\n    import subprocess\n    from pathlib import Path\n    root = Path(data_home) / "langid"\n    cache = root / "langid_trigrams_v1.npz"\n    if cache.exists():\n        z = np.load(cache)\n        return z["Xtr"], z["ytr"], z["Xte"], z["yte"], len(LANGID_LABELS)\n    repo = root / "repo"\n    if not (repo / "training_texts").exists():\n        root.mkdir(parents=True, exist_ok=True)\n        subprocess.run(["git", "clone", "-q", LANGID_REPO, str(repo)], check=True)\n        subprocess.run(["git", "-C", str(repo), "checkout", "-q", LANGID_COMMIT], check=True)\n    rng = np.random.default_rng(0)\n    Xtr, ytr = [], []\n    for k, lab in enumerate(LANGID_LABELS):\n        txt = (repo / "training_texts" / f"{lab}.txt").read_text(encoding="latin-1")\n        starts = np.arange(0, len(txt) - LANGID_CHUNK, LANGID_CHUNK)\n        for s0 in np.sort(rng.choice(starts, size=min(LANGID_PER_LANG, len(starts)), replace=False)):\n            Xtr.append(_trigram_ids(txt[s0:s0 + LANGID_CHUNK], LANGID_CHUNK))\n            ytr.append(k)\n    Xte, yte = [], []\n    for f in sorted(os.listdir(repo / "testing_texts")):\n        if f.split("_")[0] in LANGID_TEST and f.endswith("_p.txt"):\n            Xte.append(_trigram_ids((repo / "testing_texts" / f).read_text(encoding="latin-1"),\n                                    LANGID_MAXLEN))\n            yte.append(LANGID_LABELS.index(LANGID_TEST[f.split("_")[0]]))\n    pad = np.full((len(Xtr), LANGID_MAXLEN - LANGID_CHUNK), -1, np.int16)\n    Xtr = np.concatenate([np.stack(Xtr), pad], 1)\n    out = (Xtr, np.array(ytr, np.int64), np.stack(Xte), np.array(yte, np.int64))\n    np.savez_compressed(cache, Xtr=out[0], ytr=out[1], Xte=out[2], yte=out[3])\n    return (*out, len(LANGID_LABELS))\n\n\ndef load_dataset(name: str, data_home: str = "./data", seed: int = 0):\n    """Returns min-max normalised float32 (Xtr, ytr, Xte, yte) and the class count.\n    MNIST / Fashion-MNIST keep their official 60k/10k split; the other OpenML sets are\n    split 80/20, stratified, with a fixed seed."""\n    if name == "langid":  # trigram index sequences, no feature normalisation\n        return _load_langid(data_home)\n    if name == "digits":  # offline smoke-test set\n        from sklearn.datasets import load_digits\n        d = load_digits()\n        X, y, n_train = d.data.astype(np.float32), d.target, None\n    elif name == "synth":  # offline, harder: 20 overlapping classes (method prototyping only)\n        from sklearn.datasets import make_classification\n        X, y = make_classification(n_samples=12000, n_features=64, n_informative=32,\n                                   n_redundant=16, n_classes=20, n_clusters_per_class=1,\n                                   class_sep=2.0, random_state=0)\n        X, n_train = X.astype(np.float32), None\n    else:\n        from sklearn.datasets import fetch_openml\n        oname, ver, n_train = OPENML[name]\n        X, y = fetch_openml(oname, version=ver, return_X_y=True, as_frame=False,\n                            data_home=data_home, parser="auto")\n        X = X.astype(np.float32)\n    y = np.unique(y, return_inverse=True)[1].astype(np.int64)\n    if n_train:\n        Xtr, ytr, Xte, yte = X[:n_train], y[:n_train], X[n_train:], y[n_train:]\n    else:\n        from sklearn.model_selection import train_test_split\n        Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.2, stratify=y, random_state=seed)\n    lo, hi = Xtr.min(0), Xtr.max(0)\n    scale = np.where(hi > lo, hi - lo, 1.0)\n    Xtr, Xte = (Xtr - lo) / scale, np.clip((Xte - lo) / scale, 0, 1)\n    return Xtr.astype(np.float32), ytr, Xte.astype(np.float32), yte, int(y.max() + 1)\n\n\n# ----------------------------------------------------------------------------- HDC\ndef _bipolar(z: torch.Tensor) -> torch.Tensor:\n    return torch.where(z >= 0, 1, -1).to(torch.int8)\n\n\nclass Encoder:\n    """Random-projection encoder h = sign((x - mean) P). With a mean the training-set feature\n    mean is removed first, which strips the common-mode component that non-negative\n    features otherwise put into every hypervector (it wastes ADC range on the crossbar)."""\n\n    kind = "rp"\n\n    def __init__(self, n_features: int, dim: int, seed: int = 0, mean: np.ndarray | None = None):\n        g = torch.Generator().manual_seed(seed)\n        self.P = torch.randn(n_features, dim, generator=g)\n        self.mean = None if mean is None else torch.as_tensor(mean, dtype=torch.float32)\n\n    def centre(self, X) -> torch.Tensor:\n        X = torch.as_tensor(X)\n        return X - self.mean if self.mean is not None else X\n\n    def pre(self, X) -> torch.Tensor:\n        """Input vector that multiplies P (drives the encoder crossbar rows)."""\n        return self.centre(X).float()\n\n    def post(self, z: torch.Tensor) -> torch.Tensor:\n        """Projection output z = pre(x) P -> bipolar hypervector."""\n        return _bipolar(z)\n\n    @torch.no_grad()\n    def __call__(self, X: np.ndarray, bs: int = 4096) -> torch.Tensor:\n        X = self.pre(X)\n        out = torch.empty(len(X), self.P.shape[1], dtype=torch.int8)  # +/-1, 1 byte each\n        for i in range(0, len(X), bs):\n            out[i:i + bs] = self.post(X[i:i + bs] @ self.P)\n        return out\n\n\nclass NonlinearEncoder(Encoder):\n    """OnlineHD-style nonlinear encoder, binarised for the crossbar:\n    h = sign(cos(x P + b) * sin(x P)), b ~ U(0, 2 pi), with each (centred) sample scaled to\n    unit L2 norm first, as in OnlineHD / MM-HDC, so x P has unit variance."""\n\n    kind = "nonlinear"\n\n    def __init__(self, n_features: int, dim: int, seed: int = 0, mean=None):\n        super().__init__(n_features, dim, seed, mean)\n        g = torch.Generator().manual_seed(seed + 7)\n        self.b = torch.rand(dim, generator=g) * 2 * np.pi\n\n    def pre(self, X) -> torch.Tensor:\n        X = self.centre(X).float()\n        return X / X.norm(dim=1, keepdim=True).clamp_min(1e-12)\n\n    def post(self, z: torch.Tensor) -> torch.Tensor:\n        return _bipolar(torch.cos(z + self.b) * torch.sin(z))\n\n\nclass IDLevelEncoder:\n    """Record-based ID-level encoder: h = sign(sum_f ID_f * L_{q(x_f)}), with random bipolar\n    ID vectors per feature and L correlated level vectors (L_0 random; each next level flips\n    a fresh block of D / (2 (L-1)) components, so L_0 and L_{L-1} are ~orthogonal).\n    Features are expected in [0, 1] (min-max normalised); ties go to +1."""\n\n    kind = "idlevel"\n\n    def __init__(self, n_features: int, dim: int, seed: int = 0, levels: int = 16, mean=None):\n        g = torch.Generator().manual_seed(seed)\n        self.ids = torch.where(torch.rand(n_features, dim, generator=g) < 0.5, -1.0, 1.0)\n        lv = torch.empty(levels, dim)\n        lv[0] = torch.where(torch.rand(dim, generator=g) < 0.5, -1.0, 1.0)\n        order = torch.randperm(dim, generator=g)\n        step = dim // (2 * (levels - 1))\n        for k in range(1, levels):\n            lv[k] = lv[k - 1]\n            lv[k, order[(k - 1) * step:k * step]] *= -1\n        self.lv, self.levels = lv, levels\n\n    @torch.no_grad()\n    def __call__(self, X, bs: int = 2048):\n        X = torch.as_tensor(X)\n        q = torch.clamp((X * (self.levels - 1)).round().long(), 0, self.levels - 1)\n        out = torch.empty(len(X), self.ids.shape[1], dtype=torch.int8)\n        for i in range(0, len(X), bs):\n            qb = q[i:i + bs]\n            acc = torch.zeros(len(qb), self.ids.shape[1])\n            for f in range(self.ids.shape[0]):\n                acc += self.ids[f] * self.lv[qb[:, f]]\n            out[i:i + bs] = _bipolar(acc)\n        return out\n\n\nclass NGramEncoder:\n    """Character trigram encoder of the language-recognition benchmark (Rahimi et al. 2016):\n    h = sign(sum_t rho^2(L[c_{t-2}]) * rho(L[c_{t-1}]) * L[c_t]), with random bipolar letter\n    vectors L and rho a cyclic shift by one position. Implemented as h = sign(n T), where n\n    holds the trigram counts and T the 27^3 trigram hypervectors. Input: padded trigram index\n    sequences from load_dataset("langid"); ties go to +1."""\n\n    kind = "ngram"\n\n    def __init__(self, dim: int, seed: int = 0):\n        g = torch.Generator().manual_seed(seed)\n        L = torch.where(torch.rand(N_SYMBOLS, dim, generator=g) < 0.5, -1.0, 1.0)\n        R1, R2 = torch.roll(L, 1, 1), torch.roll(L, 2, 1)\n        self.T = (R2[:, None, None] * R1[None, :, None] * L[None, None, :]).reshape(-1, dim)\n\n    @torch.no_grad()\n    def __call__(self, X, bs: int = 1024):\n        X = torch.as_tensor(np.asarray(X)).long()\n        out = torch.empty(len(X), self.T.shape[1], dtype=torch.int8)\n        for i in range(0, len(X), bs):\n            xb = X[i:i + bs]\n            r, c = torch.nonzero(xb >= 0, as_tuple=True)\n            n = torch.sparse_coo_tensor(torch.stack([r, xb[r, c]]), torch.ones(len(r)),\n                                        (len(xb), self.T.shape[0])).coalesce()\n            out[i:i + bs] = _bipolar(torch.sparse.mm(n, self.T))\n        return out\n\n\ndef make_encoder(kind: str, n_features: int, dim: int, seed: int, Xtr: np.ndarray,\n                 center: bool = True):\n    if kind == "ngram":\n        return NGramEncoder(dim, seed)\n    mean = Xtr.mean(0) if center else None\n    if kind == "rp":\n        return Encoder(n_features, dim, seed, mean)\n    if kind == "rp_bipolar":  # same random projection, entries replaced by their signs (+/-1)\n        e = Encoder(n_features, dim, seed, mean)\n        e.P = torch.where(e.P >= 0, 1.0, -1.0)\n        e.kind = "rp"\n        return e\n    if kind == "nonlinear":\n        return NonlinearEncoder(n_features, dim, seed, mean)\n    if kind == "idlevel":\n        return IDLevelEncoder(n_features, dim, seed)\n    raise ValueError(kind)\n\n\n@torch.no_grad()\ndef train_prototypes(H: torch.Tensor, y: np.ndarray, n_classes: int,\n                     retrain_epochs: int = 0, lr: float = 0.05, seed: int = 0,\n                     margin: float = 0.0, adaptive: bool = False,\n                     flip_p: float = 0.0) -> torch.Tensor:\n    """Single-pass bundling, then perceptron-style retraining.\n\n    margin = 0  : classic HDC retraining (update only misclassified samples).\n    flip_p > 0 : query hypervector bits are flipped at random during retraining (noise\n                 injection as in DependableHD); combined with a fixed margin it is that baseline.\n    margin = g>0: margin-aware retraining (proposed). A sample also triggers an update when\n                  its cosine margin s_true - max_{c != true} s_c is below g, pushing it away\n                  from the strongest competitor. With g = kappa * sigma_hat (sigma_hat = std of\n                  the analog similarity error, estimated on training data), retraining trades\n                  a little digital fitting for margins that survive device noise.\n    Cosines use L2-normalised prototypes and hypervectors scaled by 1/sqrt(D)."""\n    y = torch.as_tensor(y)\n    M = torch.zeros(n_classes, H.shape[1])\n    for i in range(0, len(y), 8192):  # single-pass bundling\n        M.index_add_(0, y[i:i + 8192], H[i:i + 8192].float())\n    # class-mean initialisation: makes `lr` a relative step independent of class size\n    # (with a plain sum, one update moves a 6000-sample MNIST prototype by ~1/6000)\n    M /= torch.bincount(y, minlength=n_classes).clamp_min(1)[:, None].float()\n    g = torch.Generator().manual_seed(seed)\n    inv_sqrt_d = 1.0 / np.sqrt(H.shape[1])\n    for _ in range(retrain_epochs):\n        for idx in torch.randperm(len(y), generator=g).split(256):\n            Mn = M / M.norm(dim=1, keepdim=True).clamp_min(1e-12)\n            Hb = H[idx].float()\n            if flip_p > 0:  # DependableHD-style noise injection: random query bit flips\n                Hb = torch.where(torch.rand(Hb.shape, generator=g) < flip_p, -Hb, Hb)\n            yb = y[idx]\n            S = (Hb @ Mn.T) * inv_sqrt_d\n            s_true = S.gather(1, yb[:, None]).squeeze(1)\n            S_other = S.scatter(1, yb[:, None], float("-inf"))\n            s_comp, comp = S_other.max(1)\n            hit = (s_true - s_comp) < margin if margin > 0 else (S.argmax(1) != yb)\n            if hit.any():\n                Hw = Hb[hit]\n                if adaptive:  # OnlineHD rule: C_y += lr(1-d_y)h, C_c -= lr(1-d_c)h, d = cosine\n                    wt = (1.0 - s_true[hit])[:, None]\n                    wc = (1.0 - s_comp[hit])[:, None]\n                    M.index_add_(0, yb[hit], lr * wt * Hw)\n                    M.index_add_(0, comp[hit], -lr * wc * Hw)\n                else:\n                    M.index_add_(0, yb[hit], lr * Hw)\n                    M.index_add_(0, comp[hit], -lr * Hw)\n    return M\n\n\nMARGIN_GRID = [0.0, 0.02, 0.04, 0.06, 0.09, 0.12, 0.16, 0.20, 0.25]\n\n\nLR_GRID = [0.01, 0.03, 0.1, 0.3]\n\n\ndef _val_split(n: int, seed: int, val_frac: float = 0.15, max_train: int = 20000):\n    """Held-out split of the training data for hyperparameter tuning. On large datasets the\n    tuning-train part is capped (default 20k samples) to keep the grid search affordable;\n    the final models are always trained on the full training set."""\n    perm = torch.randperm(n, generator=torch.Generator().manual_seed(seed + 99))\n    nv = int(n * val_frac)\n    return perm[nv:nv + max_train], perm[:nv]\n\n\n@torch.no_grad()\ndef tune_lr(H, y, n_classes, epochs, seed, grid=LR_GRID, **kw) -> float:\n    """Retraining step size chosen for plain perceptron retraining on a held-out split of\n    the training data; the same lr is then used by every retraining method (fair)."""\n    tr, va = _val_split(len(y), seed)\n    scores = [accuracy_digital(quantize(train_prototypes(H[tr], y[tr.numpy()], n_classes, epochs,\n                                                         lr=lr, seed=seed, **kw), "fp"),\n                               H[va], y[va.numpy()]) for lr in grid]\n    return grid[int(np.argmax(scores))]\n\n\n@torch.no_grad()\ndef tune_margin(H: torch.Tensor, y: np.ndarray, n_classes: int, epochs: int, seed: int,\n                lr: float = 0.05, precision: str = "fp", grid=MARGIN_GRID) -> float:\n    """Digital-optimal margin chosen on a held-out split of the *training* data (no test\n    data). This is the large-margin HDC baseline; the noise-aware method adds kappa*sigma."""\n    tr, va = _val_split(len(y), seed)\n    best, best_acc = 0.0, -1.0\n    for g in grid:\n        M = train_prototypes(H[tr], y[tr.numpy()], n_classes, epochs, lr=lr, seed=seed, margin=g)\n        acc = accuracy_digital(quantize(M, precision), H[va], y[va.numpy()])\n        if acc > best_acc + 1e-9:\n            best, best_acc = g, acc\n    return best\n\n\n@torch.no_grad()\ndef cosine_margins(Mq: torch.Tensor, H: torch.Tensor, y: np.ndarray, bs: int = 8192) -> np.ndarray:\n    """Signed margin of the true class over its strongest competitor, computed on the dot\n    products the crossbar uses and expressed in cosine units of the true-class prototype:\n    (h.m_true - max_{c != true} h.m_c) / (||m_true|| sqrt(D)). Equals the plain cosine margin\n    when all prototypes have the same norm."""\n    yt = torch.as_tensor(y)\n    nrm = Mq.norm(dim=1) * np.sqrt(H.shape[1])\n    out = []\n    for i in range(0, len(H), bs):\n        S = H[i:i + bs].float() @ Mq.T\n        yb = yt[i:i + bs]\n        st = S.gather(1, yb[:, None]).squeeze(1)\n        out.append((st - S.scatter(1, yb[:, None], float("-inf")).max(1).values) / nrm[yb])\n    return torch.cat(out).numpy()\n\n\n@torch.no_grad()\ndef predict_accuracy_gaussian(Mq: torch.Tensor, H: torch.Tensor, y: np.ndarray, sigma: float,\n                              n_draws: int = 20, seed: int = 0, bs: int = 8192) -> float:\n    """Margin-to-noise model: analog accuracy predicted from the *digital* scores of every\n    class plus Gaussian noise (sigma_hat from one calibration chip). No device simulation of\n    the test set is involved. The scores are the same dot products the crossbar computes,\n    s_c = h . m_c, and the noise on class c is sigma * ||m_c|| * sqrt(D), because sigma_hat is\n    measured in per-class cosine units. (Using cosines here would be wrong whenever the\n    quantised prototypes have unequal norms and the decisions are close.)"""\n    rng = np.random.default_rng(seed)\n    scale = (Mq.norm(dim=1) * np.sqrt(H.shape[1])).numpy()\n    correct = 0.0\n    for i in range(0, len(H), bs):\n        S = (H[i:i + bs].float() @ Mq.T).numpy()\n        yb = y[i:i + bs]\n        for _ in range(n_draws):\n            correct += ((S + rng.normal(0.0, 1.0, S.shape) * (sigma * scale)).argmax(1) == yb).sum()\n    return float(correct / (n_draws * len(H)))\n\n\n@torch.no_grad()\ndef similarity_noise_sigma_times(Mq: torch.Tensor, H_cal: torch.Tensor, rpu_config, times,\n                                 in_scale: float = 1.0, seed: int = 12345) -> list[float]:\n    """sigma_hat at every time of the grid, from one calibration chip programmed once."""\n    torch.manual_seed(seed)\n    layer = build_crossbar(Mq, rpu_config)\n    layer.program_analog_weights()\n    ref = H_cal.float() @ Mq.T\n    norm = Mq.norm(dim=1) * np.sqrt(H_cal.shape[1])\n    out = []\n    for t in times:\n        layer.drift_analog_weights(t)\n        A = layer(H_cal.float() * in_scale) / in_scale\n        out.append(((A - ref) / norm).std().item())\n    return out\n\n\n@torch.no_grad()\ndef similarity_noise_sigma(Mq: torch.Tensor, H_cal: torch.Tensor, rpu_config, t: float,\n                           in_scale: float = 1.0, seed: int = 12345) -> float:\n    """Std of the analog-minus-digital cosine similarity on calibration (training) queries,\n    from one independently programmed calibration chip."""\n    torch.manual_seed(seed)\n    layer = build_crossbar(Mq, rpu_config)\n    layer.program_analog_weights()\n    layer.drift_analog_weights(t)\n    A = layer(H_cal.float() * in_scale) / in_scale\n    ref = H_cal.float() @ Mq.T\n    norm = Mq.norm(dim=1) * np.sqrt(H_cal.shape[1])\n    return ((A - ref) / norm).std().item()\n\n\ndef quantize(M: torch.Tensor, precision: str, scale: str = "mse") -> torch.Tensor:\n    """Per-class L2 normalisation, then symmetric uniform quantisation to `precision`\n    (\'fp\', \'binary\', or \'Nbit\', N >= 2) with a per-class step size.\n\n    scale=\'mse\'    : step chosen per class to minimise the quantisation MSE (grid over\n                     clipping ratios 2%..100% of max|w|); values beyond the clip saturate.\n    scale=\'maxabs\' : step = max|w| / levels (no clipping; wastes levels when a few\n                     entries are large, which is what made 2 bit worse than 1 bit)."""\n    M = M / M.norm(dim=1, keepdim=True).clamp_min(1e-12)\n    if precision == "fp":\n        return M\n    if precision == "binary":\n        return torch.where(M >= 0, 1.0, -1.0)\n    bits = int(precision.removesuffix("bit"))\n    levels = 2 ** (bits - 1) - 1  # e.g. 4 bit -> integers in [-7, 7]\n    amax = M.abs().amax(dim=1, keepdim=True).clamp_min(1e-12)\n    if scale == "maxabs":\n        st = amax / levels\n        return torch.round(M / st) * st\n    ratios = torch.linspace(0.02, 1.0, 50)\n    best_err = torch.full((M.shape[0], 1), float("inf"))\n    best_st = amax / levels\n    for r in ratios:\n        st = r * amax / levels\n        q = torch.clamp(torch.round(M / st), -levels, levels) * st\n        err = ((q - M) ** 2).sum(dim=1, keepdim=True)\n        better = err < best_err\n        best_err = torch.where(better, err, best_err)\n        best_st = torch.where(better, st, best_st)\n    return torch.clamp(torch.round(M / best_st), -levels, levels) * best_st\n\n\n@torch.no_grad()\ndef accuracy_digital(M: torch.Tensor, H: torch.Tensor, y: np.ndarray, bs: int = 8192) -> float:\n    pred = torch.cat([(H[i:i + bs].float() @ M.T).argmax(1) for i in range(0, len(H), bs)])\n    return (pred.numpy() == y).mean().item()\n\n\n# ----------------------------------------------------------------------------- crossbar\nDEVICES = ["pcm", "reram_wan", "reram_cmo"]\n# LEGACY grid of the v1 driver (sweep_hdc.py) only. Every result in the paper uses the\n# 5/3-point grid TIMES of sweep_hdc2.py (1 s, 1 d, 2 d, 30 d, 1 y; NeuRRAM 1 s, 1 d, 2 d).\n# Times after programming (s). The NeuRRAM ReRAM model only has published coefficients\n# at 1 s, 1 day and 2 days, so it is never extrapolated; 1 s / 1 day / 2 days are shared\n# by all devices for like-for-like comparison. CMO drift is a log(t) fit (extrapolated\n# beyond its characterisation window at 30 days / 1 year; reported as such).\nT_GRID = {\n    "pcm": [1.0, 3600.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n    "reram_cmo": [1.0, 3600.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n    "reram_wan": [1.0, 86400.0, 172800.0],\n}\n\n\ndef _safe_cmo_model(**kw):\n    """AIHWKit\'s CMO/HfOx model takes log10 of the drifted conductance before clamping it,\n    so when scaled-up noise pushes a device below 0 S the read-noise term becomes NaN and\n    poisons the whole column. Clamp to the physical floor g_min first (identical to the\n    original whenever the conductance stays positive, i.e. at nominal noise)."""\n    from math import log, sqrt\n\n    from aihwkit.inference import ReRamCMONoiseModel\n    from torch import randn_like\n\n    class SafeReRamCMONoiseModel(ReRamCMONoiseModel):\n        @torch.no_grad()\n        def apply_drift_noise_to_conductance(self, g_prog, drift_noise_param, t_inference):\n            if t_inference == 0:\n                return g_prog\n            g_mean = g_prog + (self.decay_dict["mean"][0] * log(t_inference) * self.drift_scale)\n            sig_rel = self.decay_dict["std"][0] * log(t_inference) + self.decay_dict["std"][1]\n            g_drift = g_mean + randn_like(g_prog) * sig_rel * self.drift_scale\n            g_drift = g_drift.clamp(min=self.g_min, max=self.g_max)\n            sig_read = (self.read_dict["K"] * torch.log10(g_drift) *\n                        sqrt(log((t_inference + self.read_dict["t_read"]) /\n                                 (2 * self.read_dict["t_read"]))))\n            g_final = g_drift + sig_read * randn_like(g_prog) * self.read_noise_scale\n            return g_final.clamp(min=self.g_min, max=self.g_max)\n\n    return SafeReRamCMONoiseModel(**kw)\n\n\ndef make_inference_config(device: str, periphery: str = "realistic", drift_comp: bool = True,\n                          noise_scale: float = 1.0):\n    from aihwkit.inference import (GlobalDriftCompensation, PCMLikeNoiseModel,\n                                   ReRamCMONoiseModel, ReRamWan2022NoiseModel)\n    from aihwkit.simulator.configs import InferenceRPUConfig\n\n    cfg = InferenceRPUConfig()\n    if device == "pcm":\n        cfg.noise_model = PCMLikeNoiseModel(g_max=25.0, prog_noise_scale=noise_scale,\n                                            read_noise_scale=noise_scale, drift_scale=noise_scale)\n    elif device == "reram_wan":\n        cfg.noise_model = ReRamWan2022NoiseModel(noise_scale=noise_scale)\n    elif device == "reram_cmo":\n        cfg.noise_model = _safe_cmo_model(prog_noise_scale=noise_scale,\n                                          read_noise_scale=noise_scale, drift_scale=noise_scale)\n    else:\n        raise ValueError(device)\n    from aihwkit.simulator.parameters.enums import BoundManagementType, NoiseManagementType\n\n    # each tile\'s weights span the full conductance range (max |w| -> g_max), so every\n    # precision gets the same signal current per device; outputs are rescaled digitally\n    cfg.mapping.weight_scaling_omega = 1.0\n    cfg.mapping.weight_scaling_columnwise = False\n    if periphery == "ideal":       # isolate the device: no DAC/ADC quantisation, no IO noise\n        cfg.forward.is_perfect = True\n    elif periphery == "realistic":\n        # single-shot read with a fixed, pre-calibrated ADC range (see calibrate_input_scale):\n        # 7-bit DAC, 9-bit ADC, output noise as in AIHWKit defaults; no dynamic input\n        # re-normalisation and no iterative re-reads, which a real macro would not do per query\n        cfg.forward.noise_management = NoiseManagementType.NONE\n        cfg.forward.bound_management = BoundManagementType.NONE\n    else:\n        raise ValueError(periphery)\n    cfg.drift_compensation = GlobalDriftCompensation() if drift_comp else None\n    return cfg\n\n\n@torch.no_grad()\ndef calibrate_input_scale(Mq: torch.Tensor, H_cal: torch.Tensor, out_bound: float = 12.0,\n                          max_input_size: int = 512, pct: float = 99.9) -> float:\n    """Read-voltage scale s so that the `pct` percentile of |tile partial sums| on\n    calibration queries lands at the ADC full scale. Done once per programmed model on\n    training data (never on test data), like an ADC range calibration on a real chip."""\n    vals = []\n    for r0 in range(0, Mq.shape[1], max_input_size):\n        W = Mq[:, r0:r0 + max_input_size]\n        W = W / W.abs().max().clamp_min(1e-12)\n        vals.append((H_cal[:, r0:r0 + max_input_size].float() @ W.T).abs().flatten())\n    p = torch.quantile(torch.cat(vals)[:2_000_000], pct / 100.0).item()\n    return min(1.0, out_bound / max(p, 1e-12))\n\n\ndef build_crossbar(Mq: torch.Tensor, rpu_config):\n    from aihwkit.nn import AnalogLinear\n    C, D = Mq.shape\n    layer = AnalogLinear(D, C, bias=False, rpu_config=rpu_config)\n    layer.set_weights(Mq.clone(), None)\n    layer.eval()\n    return layer\n\n\n@torch.no_grad()\ndef accuracy_crossbar(Mq, H, y, rpu_config, times, n_chips: int = 10, seed: int = 0,\n                      bs: int = 2048, in_scale: float = 1.0, ref_t: float | None = None,\n                      return_preds: bool = False):\n    """acc[chip, t]: each chip is an independent programming of the same prototypes.\n    Queries are applied as +/- in_scale (read-voltage scaling from the ADC calibration).\n    With return_preds, also returns predictions[chip, sample] at time ref_t."""\n    acc = np.zeros((n_chips, len(times)))\n    preds_ref = np.zeros((n_chips, len(H)), dtype=np.int16) if return_preds else None\n    for c in range(n_chips):\n        torch.manual_seed(seed * 1000 + c)\n        layer = build_crossbar(Mq, rpu_config)\n        layer.program_analog_weights()\n        for k, t in enumerate(times):\n            layer.drift_analog_weights(t)\n            outs = [layer(H[i:i + bs].float() * in_scale) for i in range(0, len(H), bs)]\n            if any(not torch.isfinite(o).all() for o in outs):\n                raise FloatingPointError(f"non-finite crossbar output at t={t} (chip {c})")\n            pred = torch.cat([o.argmax(1) for o in outs])\n            acc[c, k] = (pred.numpy() == y).mean()\n            if return_preds and t == ref_t:\n                preds_ref[c] = pred.numpy()\n    return (acc, preds_ref) if return_preds else acc\n\n\ndef encoder_input_scale(enc: Encoder, X_cal: np.ndarray) -> float:\n    """ADC range calibration of the encoder crossbar on training inputs."""\n    return calibrate_input_scale(enc.P.T.contiguous(), enc.pre(X_cal))\n\n\n@torch.no_grad()\ndef accuracy_end_to_end(enc: Encoder, Mq, X, y, rpu_config, times, n_chips: int = 10,\n                        seed: int = 0, in_scale_am: float = 1.0, in_scale_enc: float = 1.0,\n                        bs: int = 2048):\n    """End-to-end analog HDC. Per chip, the projection matrix P and the prototypes are\n    programmed into two crossbars of the same technology; both drift together. The encoder\n    crossbar computes z = pre(x) P in analog (features as DAC voltages), the digital\n    periphery applies the encoder non-linearity / sign, and the bipolar query drives the\n    prototype crossbar. Returns acc[chip, t] and the query bit-flip rate[chip, t] relative\n    to digital encoding."""\n    if not hasattr(enc, "P"):\n        raise ValueError("end-to-end analog encoding needs a projection encoder (rp/nonlinear)")\n    Xp = enc.pre(X)\n    H_dig = enc(X)\n    acc = np.zeros((n_chips, len(times)))\n    flips = np.zeros((n_chips, len(times)))\n    for c in range(n_chips):\n        torch.manual_seed(seed * 1000 + 500 + c)\n        el = build_crossbar(enc.P.T.contiguous(), rpu_config)\n        el.program_analog_weights()\n        torch.manual_seed(seed * 1000 + c)\n        am = build_crossbar(Mq, rpu_config)\n        am.program_analog_weights()\n        for k, t in enumerate(times):\n            el.drift_analog_weights(t)\n            am.drift_analog_weights(t)\n            preds, nflip = [], 0\n            for i in range(0, len(Xp), bs):\n                z = el(Xp[i:i + bs] * in_scale_enc)\n                h = enc.post(z)\n                nflip += (h != H_dig[i:i + bs]).sum().item()\n                o = am(h.float() * in_scale_am)\n                if not (torch.isfinite(z).all() and torch.isfinite(o).all()):\n                    raise FloatingPointError(f"non-finite output at t={t} (chip {c})")\n                preds.append(o.argmax(1))\n            acc[c, k] = (torch.cat(preds).numpy() == y).mean()\n            flips[c, k] = nflip / H_dig.numel()\n    return acc, flips\n\n\n@dataclass\nclass HDCModel:\n    encoder: Encoder\n    prototypes: torch.Tensor  # float, unnormalised\n    n_classes: int\n', 'analytic.py': '"""Closed-form (simulation-free) accuracy model for HDC prototypes in an analog crossbar.\n\nOnly single-device statistics enter: for a device technology and a read time t we measure,\nonce, how a weight w (normalised to the tile\'s largest |w|, as the crossbar mapping does)\nis perturbed by programming noise, drift and read noise:\n\n    m_t(w) = E[w_tilde(t)],   v_t(w) = Var[w_tilde(t)]        (device characterisation)\n\nGlobal drift compensation divides every tile output by alpha_t, which we compute exactly as\nAIHWKit does (mean |output| of one-hot reads now vs. right after programming).\n\nFor a query h in {-1,+1}^D the analog score of class c is a sum over tiles T (512 rows each):\n\n    s_c = sum_T A_T * [ sum_{j in T} h_j * w_tilde_cj / alpha_T  +  n_T,c / s ]\n\nwith A_T the tile\'s weight scale, s the read-voltage (input) scale and n_T,c ~ N(0, sigma_out^2)\nthe per-tile output noise. Taking expectations gives a deterministic, chip-independent\ndistortion of every prototype entry and a Gaussian score noise with per-class variance\n\n    mean:  mu_cj = A_T * m_t(w_cj) / alpha_T\n    var :  V_c   = sum_T A_T^2 * [ sum_{j in T} v_t(w_cj) / alpha_T^2  +  sigma_out^2 / s^2 ]\n\n(the h_j^2 = 1 factor makes V_c query independent). Errors of different devices are\nindependent, so the noise on the decision variable s_true - s_comp has variance\nV_true + V_comp: this is sigma_Delta in closed form. ADC quantisation is deterministic and\nnearly identical for nearly equal scores, so it does not enter sigma_Delta.\n\nThe predicted accuracy is the probability that argmax_c (mu-distorted score + N(0, V_c))\nreturns the true class, estimated by drawing the Gaussian part only (no device simulation).\n"""\nfrom __future__ import annotations\n\nimport functools\n\nimport numpy as np\nimport torch\n\nGRID = np.linspace(-1.0, 1.0, 81)\n\n\n@functools.lru_cache(maxsize=64)\ndef characterise(device: str, t: float, noise_scale: float = 1.0, n_rep: int = 4000,\n                 seed: int = 0):\n    """Single-device statistics m_t(w), v_t(w) on GRID and m_0(w) (right after programming).\n    Uses the same noise model object AIHWKit uses inside the tile."""\n    from hdc import make_inference_config\n\n    cfg = make_inference_config(device, "ideal", noise_scale=noise_scale)\n    nm = cfg.noise_model\n    torch.manual_seed(seed)\n    W = torch.tensor(GRID, dtype=torch.float32).repeat(n_rep, 1)  # max |w| = 1 per row block\n    prog, params = nm.apply_programming_noise(W)\n    W0 = prog  # AIHWKit takes the drift baseline right after programming\n    Wt = nm.apply_drift_noise(prog, params, t)\n    return (Wt.mean(0).numpy().astype(np.float64), Wt.var(0).numpy().astype(np.float64),\n            W0.mean(0).numpy().astype(np.float64))\n\n\ndef _interp(fn_vals, w):\n    return np.interp(w, GRID, fn_vals)\n\n\ndef score_model(Mq: torch.Tensor, device: str, t: float, in_scale: float, periphery: str,\n                noise_scale: float = 1.0, max_input_size: int = 512, out_noise: float = 0.06):\n    """Returns (M_eff, V): drift-distorted prototypes (C x D, raw units) and the per-class\n    score-noise variance V (C,) in raw dot-product units."""\n    m_t, v_t, m_0 = characterise(device, float(t), float(noise_scale))\n    M = Mq.numpy().astype(np.float64)\n    C, D = M.shape\n    M_eff = np.zeros_like(M)\n    V = np.zeros(C)\n    sig_out = 0.0 if periphery == "ideal" else out_noise\n    s = in_scale if periphery == "realistic" else 1.0\n    for r0 in range(0, D, max_input_size):\n        blk = M[:, r0:r0 + max_input_size]\n        A = np.abs(blk).max()\n        if A == 0:\n            continue\n        w = blk / A\n        mt, vt, m0 = _interp(m_t, w), _interp(v_t, w), _interp(m_0, w)\n        # AIHWKit global compensation: mean |one-hot readout| now / right after programming\n        alpha = np.abs(mt).mean() / max(np.abs(m0).mean(), 1e-12)\n        M_eff[:, r0:r0 + max_input_size] = A * mt / alpha\n        V += A ** 2 * (vt.sum(1) / alpha ** 2 + sig_out ** 2 / s ** 2)\n    return M_eff, V\n\n\n@torch.no_grad()\ndef predict_accuracy_analytic(Mq, H, y, device, t, in_scale, periphery="realistic",\n                              noise_scale=1.0, n_draws=20, seed=0, bs=8192):\n    M_eff, V = score_model(Mq, device, t, in_scale, periphery, noise_scale)\n    Me = torch.tensor(M_eff, dtype=torch.float32)\n    sd = np.sqrt(V)\n    rng = np.random.default_rng(seed)\n    correct = 0\n    for i in range(0, len(H), bs):\n        S = (H[i:i + bs].float() @ Me.T).numpy()\n        yb = y[i:i + bs]\n        for _ in range(n_draws):\n            correct += ((S + rng.normal(0, 1, S.shape) * sd).argmax(1) == yb).sum()\n    return float(correct / (n_draws * len(H)))\n\n\n\ndef predict_accuracy_quadrature(Mq, H, y, device, t, in_scale, periphery="realistic",\n                                noise_scale=1.0, n_nodes=48, bs=4096):\n    """Closed-form accuracy of the v1 Gaussian score model, without random draws.\n\n    The class scores s_c = h.mu_c + e_c have independent Gaussian errors e_c ~ N(0, V_c)\n    (every class uses its own devices; h is +/-1, so V_c does not depend on the query).\n    For a query with true class y,\n        P(correct) = int phi(z) prod_{c != y} Phi((S_y - S_c + sd_y z) / sd_c) dz,\n    a one-dimensional integral evaluated with Gauss-Hermite quadrature. The predicted\n    accuracy is its mean over the test queries."""\n    from scipy.special import log_ndtr\n    M_eff, V = score_model(Mq, device, t, in_scale, periphery, noise_scale)\n    Me = torch.tensor(M_eff, dtype=torch.float32)\n    sd = np.sqrt(V)\n    z, w = np.polynomial.hermite_e.hermegauss(n_nodes)   # weight exp(-z^2/2)\n    w = w / w.sum()\n    total = 0.0\n    for i in range(0, len(H), bs):\n        S = (H[i:i + bs].float() @ Me.T).numpy().astype(np.float64)\n        yb = np.asarray(y[i:i + bs])\n        Sy = S[np.arange(len(S)), yb][:, None, None]\n        sy = sd[yb][:, None, None]\n        arg = (Sy + sy * z[None, :, None] - S[:, None, :]) / sd[None, None, :]\n        lp = log_ndtr(arg)                                   # (B, K, C)\n        lp[np.arange(len(S)), :, yb] = 0.0                   # exclude the true class\n        total += (np.exp(lp.sum(2)) @ w).sum()\n    return float(total / len(H))\n\ndef sigma_delta_analytic(Mq, H_cal, y_cal, device, t, in_scale, periphery="realistic",\n                         noise_scale=1.0):\n    """sigma_Delta in the cosine units used by the calibration-chip estimate, for comparison."""\n    _, V = score_model(Mq, device, t, in_scale, periphery, noise_scale)\n    M = Mq.numpy()\n    norm = np.linalg.norm(M, axis=1) * np.sqrt(M.shape[1])\n    R = (H_cal.float().numpy() @ M.T) / norm\n    C = M.shape[0]\n    comp = np.where(np.arange(C)[None, :] == y_cal[:, None], -np.inf, R).argmax(1)\n    # per-sample variance of (e_true - e_comp) in cosine units, averaged\n    var = V[y_cal] / norm[y_cal] ** 2 + V[comp] / norm[comp] ** 2\n    return float(np.sqrt(var.mean()))\n\n\n# --------------------------------------------------------------------------------------\n# v2: periphery-aware closed form. The tile output is formed in the *analog* domain as\n#   u_T = s_eff * h_T . w_tilde_T + n_T          (n_T ~ N(0, sigma_out^2))\n# and is then clipped to +-out_bound and rounded to the ADC step BEFORE the digital\n# rescale A_T / (s * alpha_T). Two deterministic periphery effects therefore matter when the\n# read scale s is small (large common-mode partial sums sitting near the ADC bound):\n#   * DAC quantisation: s is realised as s_eff = round(s / inp_step) * inp_step,\n#   * read-time conductance gain (the largest programmed weight of the tile, about 1.1 for 512-row tiles of the Wan-2022 ReRAM) which\n#     drift compensation only removes AFTER the ADC.\n# Both push partial sums past the calibrated bound; clipping then removes class differences\n# (ties) and cannot be captured by a Gaussian score model. v2 keeps the per-device closed\n# form (mean m_t, variance v_t; CLT over the 512 rows of a tile) but evaluates\n# clip + ADC rounding per tile on Gaussian draws. Still no device simulation.\n# --------------------------------------------------------------------------------------\nOUT_BOUND = 12.0\nOUT_STEP = 2 * OUT_BOUND / (2 ** 9 - 2)   # 9-bit ADC (AIHWKit default out_res)\nINP_STEP = 2.0 / (2 ** 7 - 2)             # 7-bit DAC on [-1, 1] (AIHWKit default inp_res)\n\n\ndef dac_scale(s: float) -> float:\n    return float(np.round(s / INP_STEP) * INP_STEP)\n\n\n# Devices whose AIHWKit drift step re-derives conductances from the *original* targets but\n# converts back with the scale of the *programmed* weights: every tile then reads with a\n# chip-random gain G_T = max_j |w_prog,j| (the largest programmed weight of that tile),\n# e.g. ~1.1 for the Wan-2022 ReRAM model. PCM / CMO re-use the programmed conductances, G = 1.\nPROG_MAX_GAIN = {"reram_wan": True, "pcm": False, "reram_cmo": False}\n\n\n@functools.lru_cache(maxsize=64)\ndef characterise2(device: str, t: float, noise_scale: float = 1.0, n_rep: int = 4000,\n                  seed: int = 0):\n    """Like characterise, but returns intrinsic statistics with the programming-max gain of\n    the characterisation tensor divided out, plus the programming variance v_0(w)."""\n    from hdc import make_inference_config\n\n    nm = make_inference_config(device, "ideal", noise_scale=noise_scale).noise_model\n    torch.manual_seed(seed)\n    W = torch.tensor(GRID, dtype=torch.float32).repeat(n_rep, 1)\n    prog, params = nm.apply_programming_noise(W)\n    Wt = nm.apply_drift_noise(prog, params, t)\n    if PROG_MAX_GAIN[device]:\n        Wt = Wt / prog.abs().max()\n    f = lambda a: a.numpy().astype(np.float64)\n    return f(Wt.mean(0)), f(Wt.var(0)), f(prog.mean(0)), f(prog.var(0))\n\n\n_XG = np.linspace(0.8, 2.0, 1201)\n\n\ndef gain_quantiles(w: np.ndarray, m0: np.ndarray, v0: np.ndarray, n_q: int = 64):\n    """Quantiles of G = max_j |X_j|, X_j ~ N(m0(w_j), v0(w_j)) independent (exact CDF\n    as a product of single-device CDFs; only entries that can reach the max matter)."""\n    from scipy.stats import norm\n    sel = np.abs(w).ravel() > 0.6\n    mu, sd = np.abs(m0.ravel()[sel]), np.sqrt(v0.ravel()[sel]) + 1e-9\n    logF = np.zeros_like(_XG)\n    for k in range(0, len(mu), 4096):\n        a, b = mu[k:k + 4096, None], sd[k:k + 4096, None]\n        p = norm.cdf((_XG[None] - a) / b) - norm.cdf((-_XG[None] - a) / b)\n        logF += np.log(np.clip(p, 1e-300, 1)).sum(0)\n    F = np.exp(logF)\n    q = (np.arange(n_q) + 0.5) / n_q\n    return np.interp(q, F, _XG)\n\n\ndef tile_model(Mq: torch.Tensor, device: str, t: float, noise_scale: float = 1.0,\n               max_input_size: int = 512):\n    """Per tile: (row slice, A_T, alpha_T, intrinsic mean m (C x rows), summed intrinsic\n    variance per class (C,), quantiles of the read gain G_T)."""\n    m_t, v_t, m_0, v_0 = characterise2(device, float(t), float(noise_scale))\n    M = Mq.numpy().astype(np.float64)\n    out = []\n    for r0 in range(0, M.shape[1], max_input_size):\n        blk = M[:, r0:r0 + max_input_size]\n        A = np.abs(blk).max()\n        if A == 0:\n            continue\n        w = blk / A\n        mt, vt, m0 = _interp(m_t, w), _interp(v_t, w), _interp(m_0, w)\n        if PROG_MAX_GAIN[device]:\n            G = gain_quantiles(w, m0, _interp(v_0, w))\n        else:\n            G = np.ones(1)\n        # drift compensation divides by mean|read| / mean|programmed|; G_T cancels exactly\n        alpha = np.abs(mt).mean() / max(np.abs(m0).mean(), 1e-12)\n        out.append((slice(r0, r0 + max_input_size), A, alpha, mt, vt.sum(1), G))\n    return out\n\n\n@torch.no_grad()\ndef predict_accuracy_analytic2(Mq, H, y, device, t, in_scale, periphery="realistic",\n                               noise_scale=1.0, n_draws=20, seed=0, bs=4096,\n                               out_noise=0.06, return_parts=False, ablate=()):\n    """ablate: any of "dac", "gain", "clip" switches that v2 effect off (component ablation):\n    dac -> unquantised read scale, gain -> per-tile read gain fixed at 1,\n    clip -> no per-tile ADC clipping/rounding (output noise kept)."""\n    if periphery != "realistic":\n        return predict_accuracy_analytic(Mq, H, y, device, t, in_scale, periphery,\n                                         noise_scale, n_draws, seed)\n    tiles = tile_model(Mq, device, t, noise_scale)\n    s, se = float(in_scale), dac_scale(in_scale)\n    if "dac" in ablate:\n        se = s\n    rng = np.random.default_rng(seed)\n    correct = 0\n    clip_frac = 0.0\n    n_out = 0\n    for i in range(0, len(H), bs):\n        Hb = H[i:i + bs].float().numpy().astype(np.float64)\n        yb = y[i:i + bs]\n        U = [(se * (Hb[:, sl] @ mt.T), se ** 2 * vs, A / (s * al), G)\n             for sl, A, al, mt, vs, G in tiles]\n        for _ in range(n_draws):\n            S = 0.0\n            for mu, var, g, G in U:\n                Gc = 1.0 if "gain" in ablate else G[rng.integers(len(G))]  # one read gain per tile\n                u = Gc * mu + rng.standard_normal(mu.shape) * np.sqrt(Gc ** 2 * var + out_noise ** 2)\n                clip_frac += (np.abs(u) >= OUT_BOUND).sum()\n                n_out += u.size\n                if "clip" not in ablate:\n                    u = np.round(np.clip(u, -OUT_BOUND, OUT_BOUND) / OUT_STEP) * OUT_STEP\n                S = S + g * u / Gc\n            # ties (several classes clipped to the same value) resolve to the lowest index,\n            # as torch.argmax does in the crossbar evaluation\n            correct += (S.argmax(1) == yb).sum()\n    acc = float(correct / (n_draws * len(H)))\n    return (acc, clip_frac / max(n_out, 1)) if return_parts else acc\n', 'sweep_revision.py': '"""Revision experiments (reviewer round 1).\n\nStage "chips64"  - the model against a 64-chip reference (Monte-Carlo floor ~0.02 pp).\n    Subset of the core stage: 7 datasets x {rp, nonlinear} x D {512, 2048} x seed 0 x\n    {perceptron, onlinehd, largemargin} x {fp, 4bit, binary} x 3 devices, 1-day read,\n    realistic periphery: 756 points. Per point it stores\n      acc_chips      accuracy of 64 independently programmed AIHWKit chips\n      v1_quad        closed form v1 (Gauss-Hermite, no draws)\n      v2             periphery-aware model, 100 draws\n      pc_affine      strong calibration-chip baseline: per-class affine fit\n                     A_c = a_c (h.m_c) + b_c + N(0, V_c) on one programmed chip, then the\n                     exact Gaussian integral with the fitted scores and variances\n      sdiff, shat    the two calibration-chip baselines of the paper (same chip, exact integral)\n      sur_v1, sur_v2 predicted chip-to-chip distribution: 64 surrogate chips whose device\n                     values are drawn ONCE per chip from N(m_t(w), v_t(w)) (v2 also with one\n                     read gain per tile and per-tile ADC clip/round), i.e. the per-chip\n                     accuracy implied by the single-device statistics alone\n      in_scale, in_scale_full   read scale from the first 2M partial sums (as in all runs)\n                     and from all partial sums (effect of the subsampling)\nStage "onlinehd" - OnlineHD with its own step size.\n    7 datasets x {rp, nonlinear} x D {512, 2048, 8192} x seeds {0,1,2}; methods perceptron,\n    onlinehd (the shared perceptron step size, as in the paper) and onlinehd_tuned (step size\n    tuned for the OnlineHD rule on the same validation split, wider grid); fp/4bit/binary x\n    3 devices, 8 chips, 1-day read. Also the median cosine margin and sigma_Delta (one\n    calibration chip) to place every model on the margin-to-noise curve.\nOutput: results/v3_<stage>.jsonl (resumable).\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport itertools\nimport json\nimport os\nimport time\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nEPOCHS = 20\nREF_T = 86400.0\nDATASETS7 = ["isolet", "ucihar", "mnist", "fmnist", "letter", "pendigits", "satimage"]\nLR_GRID_ONLINEHD = [0.01, 0.03, 0.1, 0.3, 1.0, 3.0]\n\nSTAGES = {\n    "chips64": dict(encoders=["rp", "nonlinear"], dims=[2048, 512], seeds=[0],\n                    methods=["perceptron", "onlinehd", "largemargin"],\n                    precisions=["fp", "4bit", "binary"], n_chips=64),\n    "baselines": dict(encoders=["rp", "nonlinear"], dims=[2048, 512], seeds=[0],\n                      methods=["perceptron", "onlinehd", "largemargin"],\n                      precisions=["fp", "4bit", "binary"], n_chips=0),\n    "onlinehd": dict(encoders=["rp", "nonlinear"], dims=[8192, 2048, 512], seeds=[0, 1, 2],\n                     methods=["perceptron", "onlinehd", "onlinehd_tuned"],\n                     precisions=["fp", "4bit", "binary"], n_chips=8),\n}\nDEVICES = ["pcm", "reram_wan", "reram_cmo"]\n\n\n# ------------------------------------------------------------------------------ helpers\ndef quad_acc(S, sd, y, n_nodes=48, bs=2048):\n    """Exact mean P(argmax(S + N(0, sd^2)) == y); S (n, C); sd (C,) or (n, C)."""\n    import numpy as np\n    from scipy.special import log_ndtr\n    z, w = np.polynomial.hermite_e.hermegauss(n_nodes)\n    w = w / w.sum()\n    sd = np.broadcast_to(np.maximum(sd, 1e-12), S.shape)\n    tot = 0.0\n    for i in range(0, len(S), bs):\n        s, v, yy = S[i:i + bs], sd[i:i + bs], y[i:i + bs]\n        idx = np.arange(len(s))\n        sy, vy = s[idx, yy][:, None, None], v[idx, yy][:, None, None]\n        lp = log_ndtr((sy + vy * z[None, :, None] - s[:, None, :]) / v[:, None, :])\n        lp[idx, :, yy] = 0.0\n        tot += (np.exp(lp.sum(2)) @ w).sum()\n    return float(tot / len(S))\n\n\ndef scores(H, M, bs=8192):\n    import numpy as np\n    return np.concatenate([(H[i:i + bs].float() @ M.T).numpy().astype(np.float64)\n                           for i in range(0, len(H), bs)])\n\n\ndef full_quantile_scale(Mq, H_cal, out_bound=12.0, pct=99.9, tile=512):\n    import numpy as np\n    vals = []\n    for r0 in range(0, Mq.shape[1], tile):\n        W = Mq[:, r0:r0 + tile]\n        W = W / W.abs().max().clamp_min(1e-12)\n        vals.append((H_cal[:, r0:r0 + tile].float() @ W.T).abs().flatten().numpy())\n    p = float(np.quantile(np.concatenate(vals), pct / 100.0))\n    return min(1.0, out_bound / max(p, 1e-12))\n\n\ndef calibration_chip(Mq, H_cal, y_cal, cfg, s, Ste, yte, seed=12345):\n    """One programmed calibration chip, training queries only. Returns the predicted test\n    accuracy of three Gaussian baselines (exact integral each)."""\n    import numpy as np\n    import torch\n    from hdc import build_crossbar\n    C, D = Mq.shape\n    torch.manual_seed(seed)\n    layer = build_crossbar(Mq, cfg)\n    layer.program_analog_weights()\n    layer.drift_analog_weights(REF_T)\n    with torch.no_grad():\n        A = np.concatenate([(layer(H_cal[i:i + 2048].float() * s) / s).numpy()\n                            for i in range(0, len(H_cal), 2048)]).astype(np.float64)\n    R = scores(H_cal, Mq)\n    norm = Mq.norm(dim=1).numpy().astype(np.float64) * np.sqrt(D)\n    E = (A - R) / norm\n    comp = np.where(np.arange(C)[None, :] == y_cal[:, None], -np.inf, R / norm).argmax(1)\n    idx = np.arange(len(y_cal))\n    shat = float(E.std())\n    sdiff = float((E[idx, y_cal] - E[idx, comp]).std())\n    a, b, V = np.ones(C), np.zeros(C), np.zeros(C)\n    for c in range(C):  # per-class affine fit of the analog score on the digital score\n        X = np.c_[R[:, c], np.ones(len(R))]\n        coef, *_ = np.linalg.lstsq(X, A[:, c], rcond=None)\n        a[c], b[c] = coef\n        V[c] = np.var(A[:, c] - X @ coef)\n    return {"shat": shat, "sdiff": sdiff,\n            "pred_shat": quad_acc(Ste, shat * norm, yte),\n            "pred_sdiff": quad_acc(Ste, sdiff / np.sqrt(2) * norm, yte),\n            "pred_pc_affine": quad_acc(Ste * a + b, np.sqrt(V), yte),\n            "pc_gain": a.round(4).tolist()}\n\n\ndef calibration_chips_pooled(Mq, H_cal, y_cal, cfg, s, Ste, yte, n_cal=8, seed=12345):\n    """The calibration-chip baselines fitted on n_cal programmed chips pooled (training queries\n    only), so that chip-specific programming errors average out."""\n    import numpy as np\n    import torch\n    from hdc import build_crossbar\n    C, D = Mq.shape\n    R1 = scores(H_cal, Mq)\n    As = []\n    for k in range(n_cal):\n        torch.manual_seed(seed + k)\n        layer = build_crossbar(Mq, cfg)\n        layer.program_analog_weights()\n        layer.drift_analog_weights(REF_T)\n        with torch.no_grad():\n            As.append(np.concatenate([(layer(H_cal[i:i + 2048].float() * s) / s).numpy()\n                                      for i in range(0, len(H_cal), 2048)]).astype(np.float64))\n    A = np.concatenate(As)\n    R = np.tile(R1, (n_cal, 1))\n    yy = np.tile(y_cal, n_cal)\n    norm = Mq.norm(dim=1).numpy().astype(np.float64) * np.sqrt(D)\n    E = (A - R) / norm\n    comp = np.where(np.arange(C)[None, :] == yy[:, None], -np.inf, R / norm).argmax(1)\n    idx = np.arange(len(yy))\n    sdiff = float((E[idx, yy] - E[idx, comp]).std())\n    a, b, V = np.ones(C), np.zeros(C), np.zeros(C)\n    for c in range(C):\n        X = np.c_[R[:, c], np.ones(len(R))]\n        coef, *_ = np.linalg.lstsq(X, A[:, c], rcond=None)\n        a[c], b[c] = coef\n        V[c] = np.var(A[:, c] - X @ coef)\n    return {"sdiff8": sdiff, "pred_sdiff8": quad_acc(Ste, sdiff / np.sqrt(2) * norm, yte),\n            "pred_pc_affine8": quad_acc(Ste * a + b, np.sqrt(V), yte)}\n\n\ndef device_sigma_baseline(Mq, Ste, yte, device, s, out_noise=0.06, tile=512):\n    """Chip-free generic Gaussian: digital scores plus independent Gaussian noise whose variance\n    uses one weight-averaged device variance (mean of v_t over the stored weights) instead of\n    v_t(w) per device, and no drift distortion of the mean, no compensation factor."""\n    import numpy as np\n    from analytic import _interp, characterise\n    m_t, v_t, m_0 = characterise(device, REF_T, 1.0)\n    M = Mq.numpy().astype(np.float64)\n    C, D = M.shape\n    V = np.zeros(C)\n    for r0 in range(0, D, tile):\n        blk = M[:, r0:r0 + tile]\n        A = np.abs(blk).max()\n        vbar = _interp(v_t, blk / A).mean()\n        V += A ** 2 * (blk.shape[1] * vbar + out_noise ** 2 / s ** 2)\n    return {"pred_device_sigma": quad_acc(Ste, np.sqrt(V), yte)}\n\n\ndef surrogate_v1(Mq, H, y, device, s, n_chips, seed, out_noise=0.06, tile=512):\n    """Per-chip accuracy implied by m_t, v_t: device values drawn once per chip."""\n    import numpy as np\n    from analytic import _interp, characterise\n    m_t, v_t, m_0 = characterise(device, REF_T, 1.0)\n    M = Mq.numpy().astype(np.float64)\n    C, D = M.shape\n    mu, sd, vout = np.zeros_like(M), np.zeros_like(M), np.zeros(C)\n    for r0 in range(0, D, tile):\n        blk = M[:, r0:r0 + tile]\n        A = np.abs(blk).max()\n        w = blk / A\n        mt, vt, m0 = _interp(m_t, w), _interp(v_t, w), _interp(m_0, w)\n        al = np.abs(mt).mean() / max(np.abs(m0).mean(), 1e-12)\n        mu[:, r0:r0 + tile] = A * mt / al\n        sd[:, r0:r0 + tile] = A * np.sqrt(vt) / al\n        vout += A ** 2 * out_noise ** 2 / s ** 2\n    rng = np.random.default_rng(seed)\n    Hn = H.float().numpy()\n    acc = []\n    for _ in range(n_chips):\n        W = mu + sd * rng.standard_normal(mu.shape)\n        S = Hn @ W.T.astype(np.float32) + rng.standard_normal((len(Hn), C)) * np.sqrt(vout)\n        acc.append(float((S.argmax(1) == y).mean()))\n    return acc\n\n\ndef surrogate_v2(Mq, H, y, device, s, n_chips, seed, out_noise=0.06, tile=512):\n    """As surrogate_v1 with the v2 periphery: DAC-rounded read scale, one read gain per tile\n    and chip (exact extreme-value distribution), per-tile ADC clip and rounding."""\n    import numpy as np\n    from analytic import (OUT_BOUND, OUT_STEP, PROG_MAX_GAIN, _interp, characterise2,\n                          dac_scale, gain_quantiles)\n    m_t, v_t, m_0, v_0 = characterise2(device, REF_T, 1.0)\n    M = Mq.numpy().astype(np.float64)\n    se = dac_scale(s)\n    tiles = []\n    for r0 in range(0, M.shape[1], tile):\n        blk = M[:, r0:r0 + tile]\n        A = np.abs(blk).max()\n        w = blk / A\n        mt, vt, m0 = _interp(m_t, w), _interp(v_t, w), _interp(m_0, w)\n        G = gain_quantiles(w, m0, _interp(v_0, w)) if PROG_MAX_GAIN[device] else np.ones(1)\n        al = np.abs(mt).mean() / max(np.abs(m0).mean(), 1e-12)\n        tiles.append((slice(r0, r0 + tile), A / (s * al), mt, np.sqrt(vt), G))\n    rng = np.random.default_rng(seed)\n    Hn = H.float().numpy()\n    acc = []\n    for _ in range(n_chips):\n        S = 0.0\n        for sl, g, mt, st, G in tiles:\n            Gc = G[rng.integers(len(G))]\n            Wd = mt + st * rng.standard_normal(mt.shape)\n            u = Gc * se * (Hn[:, sl] @ Wd.T.astype(np.float32))\n            u = u + rng.standard_normal(u.shape) * out_noise\n            u = np.round(np.clip(u, -OUT_BOUND, OUT_BOUND) / OUT_STEP) * OUT_STEP\n            S = S + g * u / Gc\n        acc.append(float((S.argmax(1) == y).mean()))\n    return acc\n\n\n# ------------------------------------------------------------------------------ worker\ndef _worker(j: dict) -> list[dict]:\n    os.environ.setdefault("OMP_NUM_THREADS", "1")\n    import numpy as np\n    import torch\n    torch.set_num_threads(1)\n    from analytic import predict_accuracy_analytic2, predict_accuracy_quadrature\n    from hdc import (accuracy_crossbar, accuracy_digital, calibrate_input_scale, cosine_margins,\n                     load_dataset, make_encoder, make_inference_config, quantize,\n                     train_prototypes, tune_lr, tune_margin)\n    t0 = time.time()\n    Xtr, ytr, Xte, yte, C = load_dataset(j["dataset"], j["data_home"])\n    enc = make_encoder(j["encoder"], Xtr.shape[1], j["dim"], j["seed"], Xtr, center=True)\n    Htr, Hte = enc(Xtr), enc(Xte)\n    cal_idx = torch.randperm(len(Htr), generator=torch.Generator().manual_seed(1))[:5000]\n    H_cal, y_cal = Htr[cal_idx], ytr[cal_idx.numpy()]\n    lr = tune_lr(Htr, ytr, C, EPOCHS, j["seed"])\n    models, info = {}, {}\n    for m in j["methods"]:\n        if m == "perceptron":\n            models[m] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"])\n        elif m == "onlinehd":\n            models[m] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"], adaptive=True)\n        elif m == "onlinehd_tuned":\n            lr_o = tune_lr(Htr, ytr, C, EPOCHS, j["seed"], grid=LR_GRID_ONLINEHD, adaptive=True)\n            info[m] = {"lr_used": lr_o}\n            models[m] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr_o, seed=j["seed"], adaptive=True)\n        elif m == "largemargin":\n            g = tune_margin(Htr, ytr, C, EPOCHS, j["seed"], lr=lr)\n            info[m] = {"margin_used": g}\n            models[m] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"], margin=g)\n    t_train = time.time() - t0\n    out = []\n    for m, prec in itertools.product(j["methods"], j["precisions"]):\n        Mq = quantize(models[m], prec)\n        s = calibrate_input_scale(Mq, H_cal)\n        Ste = scores(Hte, Mq)\n        mq = cosine_margins(Mq, Hte, yte)\n        base = {"job_key": j["job_key"], "stage": j["stage"], "dataset": j["dataset"],\n                "encoder": j["encoder"], "dim": j["dim"], "seed": j["seed"], "method": m,\n                "precision": prec, "lr": lr, **info.get(m, {}),\n                "digital_acc": accuracy_digital(Mq, Hte, yte), "in_scale": s,\n                "margin_median": float(np.median(mq))}\n        if j["stage"] == "chips64":\n            base["in_scale_full"] = full_quantile_scale(Mq, H_cal)\n        for dev in DEVICES:\n            cfg = make_inference_config(dev, "realistic")\n            if j["stage"] == "baselines":\n                rec = {**base, "device": dev}\n                rec.update(calibration_chips_pooled(Mq, H_cal, y_cal, cfg, s, Ste, yte))\n                rec.update(device_sigma_baseline(Mq, Ste, yte, dev, s))\n                out.append(rec)\n                continue\n            t1 = time.time()\n            acc = accuracy_crossbar(Mq, Hte, yte, cfg, [REF_T], j["n_chips"], seed=j["seed"],\n                                    in_scale=s)[:, 0]\n            rec = {**base, "device": dev, "n_chips": j["n_chips"],\n                   "acc_chips": acc.round(6).tolist(), "acc_mean": float(acc.mean()),\n                   "sim_seconds": round(time.time() - t1, 1)}\n            rec.update(calibration_chip(Mq, H_cal, y_cal, cfg, s, Ste, yte))\n            if j["stage"] == "chips64":\n                t2 = time.time()\n                rec["v1_quad"] = predict_accuracy_quadrature(Mq, Hte, yte, dev, REF_T, s)\n                rec["v2"] = predict_accuracy_analytic2(Mq, Hte, yte, dev, REF_T, s, n_draws=100)\n                rec["pred_seconds"] = round(time.time() - t2, 2)\n                rec["sur_v1"] = surrogate_v1(Mq, Hte, yte, dev, s, 64, seed=7)\n                rec["sur_v2"] = surrogate_v2(Mq, Hte, yte, dev, s, 64, seed=7)\n            out.append(rec)\n    for r in out:\n        r["train_seconds"] = round(t_train, 1)\n        r["job_seconds"] = round(time.time() - t0, 1)\n    return out\n\n\ndef build_jobs(stage, data_home):\n    p = STAGES[stage]\n    jobs = []\n    for d, e, dim, s in itertools.product(DATASETS7, p["encoders"], p["dims"], p["seeds"]):\n        j = {"stage": stage, "dataset": d, "encoder": e, "dim": dim, "seed": s,\n             "methods": p["methods"], "precisions": p["precisions"], "n_chips": p["n_chips"]}\n        j["job_key"] = hashlib.md5(json.dumps(j, sort_keys=True).encode()).hexdigest()\n        j["data_home"] = data_home\n        jobs.append(j)\n    return jobs\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("stage", choices=list(STAGES))\n    ap.add_argument("--workers", type=int, default=os.cpu_count())\n    ap.add_argument("--outdir", default="results")\n    ap.add_argument("--data_home", default="./data")\n    ap.add_argument("--datasets", default=None, help="comma list, for a smoke test")\n    a = ap.parse_args()\n    path = Path(a.outdir) / f"v3_{a.stage}.jsonl"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    done = set()\n    if path.exists():\n        for l in path.read_text().splitlines():\n            try:\n                done.add(json.loads(l)["job_key"])\n            except (json.JSONDecodeError, KeyError):\n                pass\n    from hdc import load_dataset\n    for d in DATASETS7:\n        load_dataset(d, a.data_home)\n    jobs = [j for j in build_jobs(a.stage, a.data_home) if j["job_key"] not in done\n            and (a.datasets is None or j["dataset"] in a.datasets.split(","))]\n    print(f"[{a.stage}] {len(jobs)} jobs to run ({len(done)} done) on {a.workers} workers -> {path}",\n          flush=True)\n    t_start = time.time()\n    with ProcessPoolExecutor(max_workers=a.workers) as ex, path.open("a") as f:\n        futs = {ex.submit(_worker, j): j for j in jobs}\n        for i, fu in enumerate(as_completed(futs), 1):\n            j = futs[fu]\n            try:\n                recs = fu.result()\n            except Exception as e:\n                print(f"FAILED {j[\'dataset\']} {j[\'encoder\']} D={j[\'dim\']} seed={j[\'seed\']}: {e!r}",\n                      flush=True)\n                continue\n            for r in recs:\n                f.write(json.dumps(r) + "\\n")\n            f.flush()\n            el = time.time() - t_start\n            msg = ""\n            if a.stage == "chips64":\n                import numpy as np\n                e1 = np.mean([abs(r["v1_quad"] - r["acc_mean"]) for r in recs]) * 100\n                e2 = np.mean([abs(r["v2"] - r["acc_mean"]) for r in recs]) * 100\n                msg = f"MAE v1 {e1:.3f} v2 {e2:.3f} pp; "\n            print(f"[{i}/{len(jobs)}] {j[\'dataset\']} {j[\'encoder\']} D={j[\'dim\']} seed={j[\'seed\']}: "\n                  f"{msg}[{recs[0][\'job_seconds\']}s, elapsed {el/3600:.2f} h, "\n                  f"ETA {el / i * (len(jobs) - i) / 3600:.2f} h]", flush=True)\n    print("done", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n'}
